export interface HiddenGemItem {
  id: string
  category: string // 所属章节
  title: string // 易错点标题
  type: 'confusion' | 'trap' | 'detail' | 'contrast' // 类型：易混淆/陷阱/细节/对比
  severity: 'high' | 'medium' | 'low' // 严重程度
  question: string // 易错问题描述
  wrongAnswer: string // 典型错误答案/理解
  correctAnswer: string // 正确答案/理解
  explanation: string // 详细解释
  formula?: string // 相关公式（LaTeX）
  example?: string // 举例说明
  examTip?: string // 考试提醒
}

export interface HiddenGemCategory {
  id: string
  name: string
  icon: string
  description: string
  items: HiddenGemItem[]
}

