        explanation: '关键在于事件的转化：$\\max(X,Y) \\leq z$ 等价于 $X \\leq z$ 且 $Y \\leq z$，这是"且"的关系。$\\min(X,Y) > z$ 等价于 $X > z$ 且 $Y > z$，再用对立事件。独立时 $P(X \\leq z, Y \\leq z)=P(X \\leq z)P(Y \\leq z)$。',
        formula: '$$F_{\\max}(z) = F_X(z) \\cdot F_Y(z), \\quad F_{\\min}(z) = 1-(1-F_X(z))(1-F_Y(z))$$',
