        example: "(arcsin x)'=1/√(1-x²)，注意分母有根号；(arctan x)'=1/(1+x²)，注意分母没有根号。两个公式不可混淆",
        examTip: "arcsin和arctan的导数公式是记错重灾区：一个有根号一个没有，要反复核对",
