        wrongAnswer: "偏导数存在就能推出函数连续，和一元函数一样",
        correctAnswer: "不能！多元函数偏导数存在不能推出函数连续。一元函数中可导→连续，但多元函数中偏导数存在仅反映沿坐标轴方向的行为，不能保证沿所有方向都连续",
        explanation: '这是多元函数与一元函数的重要区别。偏导数 $f_x$ 只描述了沿 $x$ 轴方向的变化率，$f_y$ 只描述了沿 $y$ 轴方向的变化率，两者都不涉及沿其他方向（如 $y=x$ 方向）的行为。经典反例 $f(x,y)=xy/(x^2+y^2)$ 在 $(0,0)$ 处 $f_x=f_y=0$（偏导存在），但沿 $y=kx$ 趋近 $(0,0)$ 时极限为 $k/(1+k^2)$，与 $k$ 有关，故不连续。只有"可微"（所有方向一致）才能推出连续。',
        formula: "$$\\frac{\\partial f}{\\partial x}, \\frac{\\partial f}{\\partial y} \\text{ 存在} \\not\\Rightarrow f \\text{ 连续}, \\quad f \\text{ 可微} \\Rightarrow f \\text{ 连续}, \\quad \\text{偏导连续} \\Rightarrow \\text{可微} \\Rightarrow \\text{连续}$$",
        example: "f(x,y)=xy/(x²+y²)((x,y)≠(0,0)), f(0,0)=0：f_x(0,0)=f_y(0,0)=0（偏导存在），但沿y=x趋近0时f→1/2≠0（不连续）",
        examTip: "偏导存在≠连续！多元函数的'可导→连续'不再成立。只有可微才→连续",
